import{_ as e,o,c as d,a2 as r}from"./chunks/framework.CvydjLy7.js";const u=JSON.parse('{"title":"五、常见问题排查","description":"","frontmatter":{"title":"五、常见问题排查"},"headers":[],"relativePath":"ch01/05.md","filePath":"ch01/05.md","lastUpdated":1789497795000}'),a={name:"ch01/05.md"};function c(n,t,s,i,l,_){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="五、常见问题排查" tabindex="-1">五、常见问题排查 <a class="header-anchor" href="#五、常见问题排查" aria-label="Permalink to &quot;五、常见问题排查&quot;">​</a></h1><table tabindex="0"><thead><tr><th>症状</th><th>原因与解法</th></tr></thead><tbody><tr><td>启动报 <code>Port 8080 was already in use</code></td><td>端口被占用。macOS / Linux 用 <code>lsof -ti:8080 | xargs kill -9</code> 结束占用进程，或改 <code>server.port</code></td></tr><tr><td>启动报 <code>Web server failed to start. Port XXX was already in use</code>，但 <code>lsof</code> 看不到进程</td><td>端口处于 <code>TIME_WAIT</code>（刚被结束的进程尚未完全释放）。等几秒再启动，或直接换端口</td></tr><tr><td><code>java -jar</code> 报 <code>no main manifest attribute</code></td><td>用错了 jar。要跑的是 repackage 之后的可执行 jar，不是 <code>.jar.original</code>；或者检查 <code>spring-boot-maven-plugin</code> 是否配置好</td></tr><tr><td>IDE 里编译通过，命令行 <code>mvn test</code> 报 JDK 版本不兼容</td><td>Maven 用的是 <code>JAVA_HOME</code>，IDE 用的是自己配置的 SDK。执行 <code>mvn -v</code> 看 Maven 实际使用的 Java 版本，两者对齐</td></tr><tr><td>接口返回 404，但启动日志正常</td><td>控制器没被扫描到。检查控制器所在包是否在主类所在包的<strong>同级或子级</strong>；包结构问题看第 2 篇</td></tr><tr><td>中文返回乱码</td><td>确认 <code>project.build.sourceEncoding</code> 为 <code>UTF-8</code>；Spring Boot 4 默认响应编码已是 UTF-8，通常问题出在编译编码或终端编码上</td></tr></tbody></table><blockquote><p><strong>下一篇要做什么</strong></p><p>现在工程能跑起来，但业务代码放哪里、为什么这么放、自动配置到底是怎么生效的，这些还没回答。下一篇对照官方的 <em>Structuring Your Code</em> 与 <em>Auto-configuration</em> 章节，把工程的骨架与运行机制彻底讲清楚，并给案例项目补齐分层结构。</p></blockquote>',3)])])}const m=e(a,[["render",c]]);export{u as __pageData,m as default};
